fn main() {
    #[cfg(feature = "jit")]
    {
        match reth_node_ethereum::node::maybe_run_jit_helper() {
            Ok(std::ops::ControlFlow::Break(())) => return,
            Ok(std::ops::ControlFlow::Continue(())) => {}
            Err(err) => {
                eprintln!("Error: {err:?}");
                std::process::exit(1);
            }
        }
    }

    reth_cli_util::sigsegv_handler::install();

    // Enable backtraces unless a RUST_BACKTRACE value has already been explicitly provided.
    if std::env::var_os("RUST_BACKTRACE").is_none() {
        unsafe { std::env::set_var("RUST_BACKTRACE", "1") };
    }

    if let Err(err) = Cli::<EthereumChainSpecParser>::parse().run(async move |builder, _| {
        info!(target: "reth::cli", "Launching node");
        let handle = builder.node(EthereumNode::default()).launch_with_debug_capabilities().await?;

        handle.wait_for_node_exit().await
    }) {
        eprintln!("Error: {err:?}");
        std::process::exit(1);
    }
}

pub fn configure(self) -> CliApp<C, Ext, Rpc, SubCmd> {
    CliApp::new(self)
}

/// A Handle to the launched node.
#[must_use = "Needs to await the node exit future"]
pub struct NodeHandle<Node: FullNodeComponents, AddOns: RethRpcAddOns<Node>> {
    /// All node components.
    pub node: FullNode<Node, AddOns>,
    /// The exit future of the node.
    pub node_exit_future: NodeExitFuture,
}

impl<Node, AddOns> NodeHandle<Node, AddOns>
where
    Node: FullNodeComponents,
    AddOns: RethRpcAddOns<Node>,
{
    /// Waits for the node to exit, if it was configured to exit.
    pub async fn wait_for_node_exit(self) -> eyre::Result<()> {
        self.node_exit_future.await
    }
}

impl Future for NodeExitFuture {
    type Output = eyre::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if let Some(rx) = this.consensus_engine_fut.as_mut() {
            match ready!(rx.poll_unpin(cx)) {
                Ok(_) => {
                    this.consensus_engine_fut.take();
                    Poll::Ready(Ok(()))
                }
                Err(err) => Poll::Ready(Err(err)),
            }
        } else {
            Poll::Pending
        }
    }
}

    /// Execute the configured cli command.
    ///
    /// This accepts a closure that is used to launch the node via the
    /// [`NodeCommand`](reth_cli_commands::node::NodeCommand).
    pub fn run(self, launcher: impl Launcher<C, Ext>) -> Result<()>
    where
        C: ChainSpecParser<ChainSpec = ChainSpec>,
    {
        let jit_args = match &self.cli.command {
            Commands::ReExecute(cmd) => cmd.jit.clone(),
            _ => Default::default(),
        };

        let components = move |spec: Arc<ChainSpec>| {
            let (evm_config, _) =
                reth_node_ethereum::node::build_evm_config(spec.clone(), &jit_args, None)
                    .expect("failed to start revmc JIT backend");
            (evm_config, Arc::new(EthBeaconConsensus::new(spec)))
        };

        self.run_with_components::<EthereumNode>(components, async move |builder, ext| {
            launcher.entrypoint(builder, ext).await
        })
    }

    /// Execute the configured cli command with the provided [`CliComponentsBuilder`].
    ///
    /// This accepts a closure that is used to launch the node via the
    /// [`NodeCommand`](reth_cli_commands::node::NodeCommand) and allows providing custom
    /// components.
    pub fn run_with_components<N>(
        mut self,
        components: impl CliComponentsBuilder<N>,
        launcher: impl AsyncFnOnce(
            WithLaunchContext<NodeBuilder<DatabaseEnv, C::ChainSpec>>,
            Ext,
        ) -> Result<()>,
    ) -> Result<()>
    where
        N: CliNodeTypes<Primitives: NodePrimitives<BlockHeader: HeaderMut>, ChainSpec: Hardforks>,
        C: ChainSpecParser<ChainSpec = N::ChainSpec>,
    {
        let runner = match self.runner.take() {
            Some(runner) => runner,
            None => {
                let runtime_config = match &self.cli.command {
                    Commands::Node(command) => {
                        reth_tasks::RuntimeConfig::default().with_rayon(RayonConfig {
                            reserved_cpu_cores: command.engine.reserved_cpu_cores,
                            proof_storage_worker_threads: command.engine.storage_worker_count,
                            proof_account_worker_threads: command.engine.account_worker_count,
                            prewarming_threads: command.engine.prewarming_threads,
                            ..Default::default()
                        })
                    }
                    _ => reth_tasks::RuntimeConfig::default(),
                };
                CliRunner::try_with_runtime_config(runtime_config)?
            }
        };

        // Add network name if available to the logs dir
        if let Some(chain_spec) = self.cli.command.chain_spec() {
            self.cli.logs.log_file_directory =
                self.cli.logs.log_file_directory.join(chain_spec.chain().to_string());
        }

        // Apply node-specific log defaults before initializing tracing
        if matches!(self.cli.command, Commands::Node(_)) {
            self.cli.logs.apply_node_defaults();
        }

        self.init_tracing(&runner)?;

        // Deprioritize background threads spawned by tracing/OTel libraries.
        reth_tasks::utils::deprioritize_background_threads();

        // Install the prometheus recorder to be sure to record all metrics
        install_prometheus_recorder();

        run_commands_with::<C, Ext, Rpc, N, SubCmd>(self.cli, runner, components, launcher)
    }

    /// Initializes tracing with the configured options.
    ///
    /// See [`Cli::init_tracing`] for more information.
    pub fn init_tracing(&mut self, runner: &CliRunner) -> Result<()> {
        if let Some(layers) = self.layers.take() {
            self.guard = Some(self.cli.init_tracing(runner, layers)?);
        }

        Ok(())
    }
}

/// Run CLI commands with the provided runner, components and launcher.
/// This is the shared implementation used by both `CliApp` and Cli methods.
pub(crate) fn run_commands_with<C, Ext, Rpc, N, SubCmd>(
    cli: Cli<C, Ext, Rpc, SubCmd>,
    runner: CliRunner,
    components: impl CliComponentsBuilder<N>,
    launcher: impl AsyncFnOnce(
        WithLaunchContext<NodeBuilder<DatabaseEnv, C::ChainSpec>>,
        Ext,
    ) -> Result<()>,
) -> Result<()>
where
    C: ChainSpecParser<ChainSpec = N::ChainSpec>,
    Ext: clap::Args + fmt::Debug,
    Rpc: RpcModuleValidator,
    N: CliNodeTypes<Primitives: NodePrimitives<BlockHeader: HeaderMut>, ChainSpec: Hardforks>,
    SubCmd: ExtendedCommand + Subcommand + fmt::Debug,
{
    let rt = runner.runtime();

    match cli.command {
        Commands::Node(command) => {
            // Validate RPC modules using the configured validator
            if let Some(http_api) = &command.rpc.http_api {
                Rpc::validate_selection(http_api, "http.api").map_err(|e| eyre!("{e}"))?;
            }
            if let Some(ws_api) = &command.rpc.ws_api {
                Rpc::validate_selection(ws_api, "ws.api").map_err(|e| eyre!("{e}"))?;
            }

            runner.run_command_until_exit(|ctx| {
                command.execute(ctx, FnLauncher::new::<C, Ext>(launcher))
            })
        }

/// Executes the given _async_ command on the tokio runtime until the command future resolves or
/// until the process receives a `SIGINT` or `SIGTERM` signal.
///
/// Tasks spawned by the command via the [`TaskExecutor`] are shut down and an attempt is made
/// to drive their shutdown to completion after the command has finished.
pub fn run_command_until_exit<F, E>(
    self,
    command: impl FnOnce(CliContext) -> F,
) -> Result<(), E>
where
    F: Future<Output = Result<(), E>>,
    E: Send
        + Sync
        + std::fmt::Display
        + From<std::io::Error>
        + From<reth_tasks::PanickedTaskError>
        + 'static,
{
    let (context, task_manager_handle) = cli_context(&self.runtime);

    // Executes the command until it finished or ctrl-c was fired
    let command_res = self.runtime.handle().block_on(run_to_completion_or_panic(
        task_manager_handle,
        run_until_ctrl_c(command(context)),
    ));

    if let Err(err) = &command_res {
        error!(target: "reth::cli", %err, "shutting down due to error");
    } else {
        debug!(target: "reth::cli", "shutting down gracefully");
        // after the command has finished or exit signal was received we shutdown the
        // runtime which fires the shutdown signal to all tasks spawned via the task
        // executor and awaiting on tasks spawned with graceful shutdown
        self.runtime.graceful_shutdown_with_timeout(self.config.graceful_shutdown_timeout);
    }

    runtime_shutdown(self.runtime, true);

    command_res
}

/// A function-based adapter implementation of the [`Launcher`] trait.
///
/// This struct adapts existing closures to work with the new [`Launcher`] trait,
/// maintaining backward compatibility with current node implementations while
/// enabling the transition to the more flexible trait-based approach.
pub struct FnLauncher<F> {
    /// The function to execute when launching the node
    func: F,
}

impl<F> FnLauncher<F> {
    /// Creates a new function launcher adapter.
    ///
    /// Type parameters `C` and `Ext` help the compiler infer correct types
    /// since they're not stored in the struct itself.
    ///
    /// # Arguments
    ///
    /// * `func` - Function that configures and launches a node
    pub fn new<C, Ext>(func: F) -> Self
    where
        C: ChainSpecParser,
        F: AsyncFnOnce(
            WithLaunchContext<NodeBuilder<DatabaseEnv, C::ChainSpec>>,
            Ext,
        ) -> eyre::Result<()>,
    {
        Self { func }
    }
}

impl<F> fmt::Debug for FnLauncher<F> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("FnLauncher").field("func", &"<function>").finish()
    }
}

impl<C, Ext, F> Launcher<C, Ext> for FnLauncher<F>
where
    C: ChainSpecParser,
    Ext: clap::Args + fmt::Debug,
    F: AsyncFnOnce(
        WithLaunchContext<NodeBuilder<DatabaseEnv, C::ChainSpec>>,
        Ext,
    ) -> eyre::Result<()>,
{
    fn entrypoint(
        self,
        builder: WithLaunchContext<NodeBuilder<DatabaseEnv, C::ChainSpec>>,
        builder_args: Ext,
    ) -> impl Future<Output = eyre::Result<()>> {
        (self.func)(builder, builder_args)
    }
}

/// Runs the given future to completion or until a critical task panicked.
///
/// Returns the error if a task panicked, or the given future returned an error.
async fn run_to_completion_or_panic<F, E>(
    task_manager_handle: JoinHandle<Result<(), PanickedTaskError>>,
    fut: F,
) -> Result<(), E>
where
    F: Future<Output = Result<(), E>>,
    E: Send + Sync + From<reth_tasks::PanickedTaskError> + 'static,
{
    let fut = pin!(fut);
    tokio::select! {
        task_manager_result = task_manager_handle => {
            if let Ok(Err(panicked_error)) = task_manager_result {
                return Err(panicked_error.into());
            }
        },
        res = fut => res?,
    }
    Ok(())
}

/// Runs the future to completion or until:
/// - `ctrl-c` is received.
/// - `SIGTERM` is received (unix only).
async fn run_until_ctrl_c<F, E>(fut: F) -> Result<(), E>
where
    F: Future<Output = Result<(), E>>,
    E: Send + Sync + 'static + From<std::io::Error>,
{
    let ctrl_c = tokio::signal::ctrl_c();

    #[cfg(unix)]
    {
        let mut stream = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())?;
        let sigterm = stream.recv();
        let sigterm = pin!(sigterm);
        let ctrl_c = pin!(ctrl_c);
        let fut = pin!(fut);

        tokio::select! {
            _ = ctrl_c => {
                info!(target: "reth::cli", "Received ctrl-c");
            },
            _ = sigterm => {
                info!(target: "reth::cli", "Received SIGTERM");
            },
            res = fut => res?,
        }
    }

    #[cfg(not(unix))]
    {
        let ctrl_c = pin!(ctrl_c);
        let fut = pin!(fut);

        tokio::select! {
            _ = ctrl_c => {
                info!(target: "reth::cli", "Received ctrl-c");
            },
            res = fut => res?,
        }
    }

    Ok(())
}

/// Creates a new [`EngineApiTreeHandler`] instance and spawns it in its
/// own thread.
///
/// Returns the sender through which incoming requests can be sent to the task and the receiver
/// end of a [`EngineApiEvent`] unbounded channel to receive events from the engine.
#[expect(clippy::complexity)]
pub fn spawn_new(
    provider: P,
    consensus: Arc<dyn FullConsensus<N>>,
    payload_validator: V,
    persistence: PersistenceHandle<N>,
    payload_builder: PayloadBuilderHandle<T>,
    canonical_in_memory_state: CanonicalInMemoryState<N>,
    overlay_manager: OverlayManager<N>,
    config: TreeConfig,
    kind: EngineApiKind,
    evm_config: C,
    runtime: reth_tasks::Runtime,
) -> (Sender<FromEngine<EngineApiRequest<T, N>, N::Block>>, UnboundedReceiver<EngineApiEvent<N>>)
{
    let best_block_number = provider.best_block_number().unwrap_or(0);
    let header = provider.sealed_header(best_block_number).ok().flatten().unwrap_or_default();

    let persistence_state = PersistenceState {
        last_persisted_block: BlockNumHash::new(best_block_number, header.hash()),
        last_state_trie_persisted_block: BlockNumHash::new(best_block_number, header.hash()),
        rx: None,
    };

    let (tx, outgoing) = unbounded_channel();
    let state = EngineApiTreeState::new(
        config.block_buffer_limit(),
        config.max_invalid_header_cache_length(),
        config.invalid_header_hit_eviction_threshold(),
        header.num_hash(),
        kind,
        overlay_manager,
    );

    let task = Self::new(
        provider,
        consensus,
        payload_validator,
        tx,
        state,
        canonical_in_memory_state,
        persistence,
        persistence_state,
        payload_builder,
        config,
        kind,
        evm_config,
        runtime,
    );
    let incoming = task.incoming_tx.clone();
    spawn_os_thread("engine", || {
        increase_thread_priority();
        task.run()
    });
    (incoming, outgoing)
}

/// Convenience function to start the network tasks.
///
/// Spawns the configured network and associated tasks and returns the [`NetworkHandle`]
/// connected to that network.
pub fn start_network<N, Pool>(
    &self,
    builder: NetworkBuilder<(), (), N>,
    pool: Pool,
) -> NetworkHandle<N>
where
    N: NetworkPrimitives,
    Pool: TransactionPool<
            Transaction: PoolTransaction<
                Consensus = N::BroadcastedTransaction,
                Pooled = N::PooledTransaction,
            >,
        > + Unpin
        + 'static,
    Node::Provider: BlockReaderFor<N>,
{
    self.start_network_with(
        builder,
        pool,
        self.config().network.transactions_manager_config(),
        self.config().network.tx_propagation_policy,
    )
}

/// Convenience function to start the network tasks.
///
/// Accepts the config for the transaction task and the policy for propagation.
/// Uses the default [`StrictEthAnnouncementFilter`] for announcement filtering.
///
/// Spawns the configured network and associated tasks and returns the [`NetworkHandle`]
/// connected to that network.
pub fn start_network_with<Pool, N, Policy>(
    &self,
    builder: NetworkBuilder<(), (), N>,
    pool: Pool,
    tx_config: TransactionsManagerConfig,
    propagation_policy: Policy,
) -> NetworkHandle<N>
where
    N: NetworkPrimitives,
    Pool: TransactionPool<
            Transaction: PoolTransaction<
                Consensus = N::BroadcastedTransaction,
                Pooled = N::PooledTransaction,
            >,
        > + Unpin
        + 'static,
    Node::Provider: BlockReaderFor<N>,
    Policy: TransactionPropagationPolicy<N>,
{
    self.start_network_with_policies(
        builder,
        pool,
        tx_config,
        propagation_policy,
        StrictEthAnnouncementFilter::default(),
    )
}

/// Convenience function to start the network tasks with custom policies.
///
/// Accepts the config for the transaction task, the policy for propagation,
/// and a custom announcement filter. This is useful for configuring which tx types are accepted
/// in announcements.
///
/// Spawns the configured network and associated tasks and returns the [`NetworkHandle`]
/// connected to that network.
pub fn start_network_with_policies<Pool, N, PropPolicy, AnnPolicy>(
    &self,
    builder: NetworkBuilder<(), (), N>,
    pool: Pool,
    tx_config: TransactionsManagerConfig,
    propagation_policy: PropPolicy,
    announcement_policy: AnnPolicy,
) -> NetworkHandle<N>
where
    N: NetworkPrimitives,
    Pool: TransactionPool<
            Transaction: PoolTransaction<
                Consensus = N::BroadcastedTransaction,
                Pooled = N::PooledTransaction,
            >,
        > + Unpin
        + 'static,
    Node::Provider: BlockReaderFor<N>,
    PropPolicy: TransactionPropagationPolicy<N>,
    AnnPolicy: AnnouncementFilteringPolicy<N>,
{
    let (handle, network, txpool, eth) = builder
        .transactions_with_policies(
            pool.clone(),
            tx_config,
            propagation_policy,
            announcement_policy,
        )
        .map_transactions(|transactions| {
            if let Some(cache) = self.sender_recovery_cache.clone() {
                transactions.with_sender_recovery_cache(cache)
            } else {
                transactions
            }
        })
        .request_handler_with_blob_store(self.provider().clone(), pool.blob_store())
        .split_with_handle();

    self.executor.spawn_critical_blocking_task("p2p txpool", txpool);
    self.executor.spawn_critical_blocking_task("p2p eth request handler", eth);

    let default_peers_path = self.config().datadir().known_peers();
    let known_peers_file = self.config().network.persistent_peers_file(default_peers_path);
    self.executor.spawn_critical_with_graceful_shutdown_signal(
        "p2p network task",
        |shutdown| {
            network.run_until_graceful_shutdown(shutdown, |network| {
                if let Some(peers_file) = known_peers_file {
                    let num_known_peers = network.num_known_peers();
                    trace!(target: "reth::cli", peers_file=?peers_file, num_peers=%num_known_peers, "Saving current peers");
                    match network.write_peers_to_file(peers_file.as_path()) {
                        Ok(_) => {
                            info!(target: "reth::cli", peers_file=?peers_file, "Wrote network peers to file");
                        }
                        Err(err) => {
                            warn!(target: "reth::cli", %err, "Failed to write network peers to file");
                        }
                    }
                }
            })
        },
    );

    handle
}

pub async fn execute<L>(self, ctx: CliContext, launcher: L) -> eyre::Result<()>
where
    L: Launcher<C, Ext>,
{
    tracing::info!(target: "reth::cli", version = ?version::version_metadata().short_version, "Starting {}",  version::version_metadata().name_client);

    let Self {
        datadir,
        config,
        chain,
        metrics,
        instance,
        with_unused_ports,
        network,
        rpc,
        txpool,
        builder,
        debug,
        db,
        dev,
        pruning,
        engine,
        era,
        static_files,
        storage,
        jit,
        ext,
    } = self;

    engine.validate()?;

    // set up node config
    let mut node_config = NodeConfig {
        datadir,
        config,
        chain,
        metrics,
        instance,
        network,
        rpc,
        txpool,
        builder,
        debug,
        db,
        dev,
        pruning,
        engine,
        era,
        static_files,
        storage,
        jit,
    };

    let data_dir = node_config.datadir();
    let db_path = data_dir.db();

    tracing::info!(target: "reth::cli", path = ?db_path, "Opening database");
    let database = init_db(db_path.clone(), self.db.database_args())?
        .with_metrics_if(self.db.metrics_enabled());

    if with_unused_ports {
        node_config = node_config.with_unused_ports();
    }

    let builder = NodeBuilder::new(node_config)
        .with_database(database)
        .with_launch_context(ctx.task_executor);

    launcher.entrypoint(builder, ext).await
}

async fn launch_node<N, DB, T, CB, AO>(
    self,
    target: NodeBuilderWithComponents<T, CB, AO>,
) -> eyre::Result<NodeHandle<NodeAdapter<T, CB::Components>, AO>>
where
    N: Node<RethFullAdapter<DB, N>> + NodeTypesForProvider,
    DB: Database + DatabaseMetrics + Clone + Unpin + 'static,
    T: FullNodeTypes<
        Types = N,
        Provider = BlockchainProvider<NodeTypesWithDBAdapter<N, DB>>,
        DB = DB,
    >,
    CB: NodeComponentsBuilder<T>,
    AO: RethRpcAddOns<NodeAdapter<T, CB::Components>>
        + EngineValidatorAddOn<NodeAdapter<T, CB::Components>>,
{
    let Self { ctx, engine_tree_config } = self;
    let NodeBuilderWithComponents {
        adapter: NodeTypesAdapter { database },
        rocksdb_provider,
        components_builder,
        add_ons: AddOns { hooks, exexs: installed_exex, add_ons },
        config,
    } = target;
    let NodeHooks { on_component_initialized, on_node_started, .. } = hooks;

    // Create the overlay manager that will be shared across the provider and engine.
    let overlay_manager = OverlayManager::<N::Primitives>::new(
        ctx.task_executor.state_trie_overlay_worker_pool(),
    );
    let disabled_stages = N::disabled_stages();

    // setup the launch context
    let ctx = ctx
        .with_configured_globals(engine_tree_config.reserved_cpu_cores())
        // load the toml config
        .with_loaded_toml_config(config)?
        // add resolved peers
        .with_resolved_peers()?
        // attach the database
        .attach(database.clone())
        // ensure certain settings take effect
        .with_adjusted_configs()
        // Create the provider factory with the shared overlay manager
        .with_provider_factory::<_, <CB::Components as NodeComponents<T>>::Evm>(
            overlay_manager.clone(),
            rocksdb_provider,
            disabled_stages,
        )
        .await?
        .inspect(|_| {
            info!(target: "reth::cli", "Database opened");
        })
        .with_prometheus_server().await?
        .inspect(|this| {
            debug!(target: "reth::cli", chain=%this.chain_id(), genesis=?this.genesis_hash(), "Initializing genesis");
        })
        .with_genesis()?
        .inspect(|this: &LaunchContextWith<Attached<WithConfigs<<T::Types as NodeTypes>::ChainSpec>, _>>| {
            info!(target: "reth::cli", "\n{}", this.chain_spec().display_hardforks());
            let settings = this.provider_factory().cached_storage_settings();
            let pruning_mode =
                PruneConfigKind::from_config(&this.prune_config(), this.chain_spec().as_ref()).as_str();
            info!(target: "reth::cli", ?settings, ?pruning_mode, "Loaded storage settings");
        })
        .with_metrics_task()
        // passing FullNodeTypes as type parameter here so that we can build
        // later the components.
        .with_blockchain_db::<T, _>(move |provider_factory| {
            Ok(BlockchainProvider::new(provider_factory)?)
        })?
        .with_components(components_builder, on_component_initialized).await?;

impl<Node, PoolB, PayloadB, NetworkB, ExecB, ConsB> NodeComponentsBuilder<Node>
    for ComponentsBuilder<Node, PoolB, PayloadB, NetworkB, ExecB, ConsB>
where
    Node: FullNodeTypes,
    PoolB: PoolBuilder<Node, ExecB::EVM, Pool: TransactionPool>,
    NetworkB: NetworkBuilder<
        Node,
        PoolB::Pool,
        Network: FullNetwork<
            Primitives: NetPrimitivesFor<
                PrimitivesTy<Node::Types>,
                PooledTransaction = PoolPooledTx<PoolB::Pool>,
            >,
        >,
    >,
    PayloadB: PayloadServiceBuilder<Node, PoolB::Pool, ExecB::EVM>,
    ExecB: ExecutorBuilder<Node>,
    ConsB: ConsensusBuilder<Node>,
{
    type Components =
        Components<Node, NetworkB::Network, PoolB::Pool, ExecB::EVM, ConsB::Consensus>;

    async fn build_components(
        self,
        context: &BuilderContext<Node>,
    ) -> eyre::Result<Self::Components> {
        let Self {
            pool_builder,
            payload_builder,
            network_builder,
            executor_builder,
            consensus_builder,
            _marker,
        } = self;

        let evm_config = executor_builder.build_evm(context).await?;
        let pool = pool_builder.build_pool(context, evm_config.clone()).await?;
        let network = network_builder.build_network(context, pool.clone()).await?;
        let payload_builder_handle = payload_builder
            .spawn_payload_builder_service(context, pool.clone(), evm_config.clone())
            .await?;
        let consensus = consensus_builder.build_consensus(context).await?;

        Ok(Components {
            transaction_pool: pool,
            evm_config,
            network,
            payload_builder_handle,
            consensus,
        })
    }
}

/// Preconfigures the node with a specific node implementation.
///
/// This is a convenience method that sets the node's types and components in one call.
pub fn node<N>(
    self,
    node: N,
) -> WithLaunchContext<
    NodeBuilderWithComponents<RethFullAdapter<DB, N>, N::ComponentsBuilder, N::AddOns>,
>
where
    N: Node<RethFullAdapter<DB, N>, ChainSpec = ChainSpec> + NodeTypesForProvider,
{
    self.with_types().with_components(node.components_builder()).with_add_ons(node.add_ons())
}

impl<N> Node<N> for EthereumNode
where
    N: FullNodeTypes<Types = Self>,
{
    type ComponentsBuilder = ComponentsBuilder<
        N,
        EthereumPoolBuilder,
        BasicPayloadServiceBuilder<EthereumPayloadBuilder>,
        EthereumNetworkBuilder,
        EthereumExecutorBuilder,
        EthereumConsensusBuilder,
    >;

    type AddOns =
        EthereumAddOns<NodeAdapter<N>, EthereumEthApiBuilder, EthereumEngineValidatorBuilder>;

    fn components_builder(&self) -> Self::ComponentsBuilder {
        Self::components()
    }

    fn add_ons(&self) -> Self::AddOns {
        EthereumAddOns::default()
    }
}

impl<Node, Pool> NetworkBuilder<Node, Pool> for EthereumNetworkBuilder
where
    Node: FullNodeTypes<Types: NodeTypes<ChainSpec: Hardforks>>,
    Pool: TransactionPool<Transaction: PoolTransaction<Consensus = TxTy<Node::Types>>>
        + Unpin
        + 'static,
{
    type Network =
        NetworkHandle<BasicNetworkPrimitives<PrimitivesTy<Node::Types>, PoolPooledTx<Pool>>>;

    async fn build_network(
        self,
        ctx: &BuilderContext<Node>,
        pool: Pool,
    ) -> eyre::Result<Self::Network> {
        let network = ctx.network_builder().await?;
        let handle = ctx.start_network(network, pool);
        info!(target: "reth::cli", enode=%handle.local_node_record(), "P2P networking initialized");
        Ok(handle)
    }
}

impl<Node, Pool, PB, EvmConfig> PayloadServiceBuilder<Node, Pool, EvmConfig>
    for BasicPayloadServiceBuilder<PB>
where
    Node: FullNodeTypes,
    Pool: TransactionPool,
    EvmConfig: Send,
    PB: PayloadBuilderBuilder<Node, Pool, EvmConfig>,
{
    async fn spawn_payload_builder_service(
        self,
        ctx: &BuilderContext<Node>,
        pool: Pool,
        evm_config: EvmConfig,
    ) -> eyre::Result<PayloadBuilderHandle<<Node::Types as NodeTypes>::Payload>> {
        let Self { payload_builder_builder, pre_cache_state } = self;
        let payload_builder =
            payload_builder_builder.build_payload_builder(ctx, pool, evm_config).await?;

        let conf = ctx.config().builder.clone();

        let payload_job_config = BasicPayloadJobGeneratorConfig::default()
            .interval(conf.interval)
            .deadline(conf.deadline)
            .max_payload_tasks(conf.max_payload_tasks)
            .pre_cache_state(pre_cache_state);

        let payload_generator = BasicPayloadJobGenerator::with_builder(
            ctx.provider().clone(),
            ctx.task_executor().clone(),
            payload_job_config,
            payload_builder,
        );
        let (payload_service, payload_service_handle) =
            PayloadBuilderService::<_, _, <Node::Types as NodeTypes>::Payload>::new(
                payload_generator,
                ctx.provider().canonical_state_stream(),
            );

        ctx.task_executor().spawn_critical_os_thread(
            "payload-service",
            "payload builder service",
            payload_service,
        );

        Ok(payload_service_handle)
    }
}

