    /// Spawns the engine services and returns the [`ChainOrchestrator`] driving them.
    pub fn build(
        self,
    ) -> EngineOrchestrator<N::Payload, N::Primitives, Client, S, PipelineSync<N>> {
        let Self {
            engine_kind,
            consensus,
            client,
            incoming_requests,
            pipeline,
            pipeline_task_spawner,
            provider,
            blockchain_db,
            pruner,
            payload_builder,
            payload_validator,
            overlay_manager,
            tree_config,
            sync_metrics_tx,
            evm_config,
            runtime,
        } = self;

        let downloader = BasicBlockDownloader::new(client, consensus.clone());

        let persistence_handle =
            PersistenceHandle::<N::Primitives>::spawn_service(provider, pruner, sync_metrics_tx);

        let canonical_in_memory_state = blockchain_db.canonical_in_memory_state();

        let (to_tree_tx, from_tree) = EngineApiTreeHandler::spawn_new(
            blockchain_db,
            consensus,
            payload_validator,
            persistence_handle,
            payload_builder,
            canonical_in_memory_state,
            overlay_manager,
            tree_config,
            engine_kind,
            evm_config,
            runtime,
        );

        let engine_handler = EngineApiRequestHandler::new(to_tree_tx, from_tree);
        let handler = EngineHandler::new(engine_handler, downloader, incoming_requests);

        let backfill_sync = PipelineSync::new(pipeline, pipeline_task_spawner);

        ChainOrchestrator::new(handler, backfill_sync)
    }
}

impl<N: ProviderNodeTypes> PipelineSync<N> {
    /// Create a new instance.
    pub fn new(pipeline: Pipeline<N>, pipeline_task_spawner: Runtime) -> Self {
        Self {
            pipeline_task_spawner,
            pipeline_state: PipelineState::Idle(Some(Box::new(pipeline))),
            pending_pipeline_target: None,
        }
    }

    /// Returns `true` if a pipeline target is queued and will be triggered on the next `poll`.
    #[expect(dead_code)]
    const fn is_pipeline_sync_pending(&self) -> bool {
        self.pending_pipeline_target.is_some() && self.pipeline_state.is_idle()
    }

    /// Returns `true` if the pipeline is idle.
    const fn is_pipeline_idle(&self) -> bool {
        self.pipeline_state.is_idle()
    }

    /// Returns `true` if the pipeline is active.
    const fn is_pipeline_active(&self) -> bool {
        !self.is_pipeline_idle()
    }

    /// Sets a new target to sync the pipeline to.
    ///
    /// But ensures the target is not the zero hash.
    fn set_pipeline_sync_target(&mut self, target: PipelineTarget) {
        if target.sync_target().is_some_and(|target| target.is_zero()) {
            trace!(
                target: "consensus::engine::sync",
                "Pipeline target cannot be zero hash."
            );
            // precaution to never sync to the zero hash
            return
        }
        self.pending_pipeline_target = Some(target);
    }

    /// This will spawn the pipeline if it is idle and a target is set or if the pipeline is set to
    /// run continuously.
    fn try_spawn_pipeline(&mut self) -> Option<BackfillEvent> {
        match &mut self.pipeline_state {
            PipelineState::Idle(pipeline) => {
                let target = self.pending_pipeline_target.take()?;
                let (tx, rx) = oneshot::channel();

                let pipeline = pipeline.take().expect("exists");
                self.pipeline_task_spawner.spawn_critical_blocking_task(
                    "pipeline task",
                    async move {
                        let result = pipeline.run_as_fut(Some(target)).await;
                        let _ = tx.send(result);
                    },
                );
                self.pipeline_state = PipelineState::Running(rx);

                Some(BackfillEvent::Started(target))
            }
            PipelineState::Running(_) => None,
        }
    }

    /// Advances the pipeline state.
    ///
    /// This checks for the result in the channel, or returns pending if the pipeline is idle.
    fn poll_pipeline(&mut self, cx: &mut Context<'_>) -> Poll<BackfillEvent> {
        let res = match self.pipeline_state {
            PipelineState::Idle(_) => return Poll::Pending,
            PipelineState::Running(ref mut fut) => {
                ready!(fut.poll_unpin(cx))
            }
        };
        let ev = match res {
            Ok((pipeline, result)) => {
                self.pipeline_state = PipelineState::Idle(Some(Box::new(pipeline)));
                BackfillEvent::Finished(result)
            }
            Err(why) => {
                // failed to receive the pipeline
                BackfillEvent::TaskDropped(why.to_string())
            }
        };
        Poll::Ready(ev)
    }
}

impl<N: ProviderNodeTypes> BackfillSync for PipelineSync<N> {
    fn on_action(&mut self, event: BackfillAction) {
        match event {
            BackfillAction::Start(target) => self.set_pipeline_sync_target(target),
        }
    }

    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<BackfillEvent> {
        // try to spawn a pipeline if a target is set
        if let Some(event) = self.try_spawn_pipeline() {
            return Poll::Ready(event)
        }

        // make sure we poll the pipeline if it's active, and return any ready pipeline events
        if self.is_pipeline_active() {
            // advance the pipeline
            if let Poll::Ready(event) = self.poll_pipeline(cx) {
                return Poll::Ready(event)
            }
        }

        Poll::Pending
    }
}

let RpcHandle {
    rpc_server_handles,
    rpc_registry,
    engine_events,
    beacon_engine_handle,
    engine_shutdown: _,
} = add_ons.launch_add_ons(add_ons_ctx).await?;

// Create engine shutdown handle
let (engine_shutdown, shutdown_rx) = EngineShutdown::new();

// Run consensus engine to completion
let initial_target = ctx.initial_backfill_target(disabled_stages)?;

let consensus_engine = move |mut on_graceful_shutdown| async move {
    if let Some(initial_target) = initial_target {
        debug!(target: "reth::cli", %initial_target,  "start backfill sync");
        // network_handle's sync state is already initialized at Syncing
        orchestrator.start_backfill_sync(initial_target);
    } else if startup_sync_state_idle {
        network_handle.update_sync_state(SyncState::Idle);
    }

    let mut res = Ok(());
    let mut shutdown_rx = shutdown_rx.fuse();

    // advance the chain and await payloads built locally to add into the engine api
    // tree handler to prevent re-execution if that block is received as payload from
    // the CL
    loop {
        tokio::select! {
            event = orchestrator.next() => {
                let Some(event) = event else { break };
                debug!(target: "reth::cli", "Event: {event}");
                match event {
                    ChainEvent::BackfillSyncFinished => {
                        if terminate_after_backfill {
                            debug!(target: "reth::cli", "Terminating after initial backfill");
                            break
                        }
                        if startup_sync_state_idle {
                            network_handle.update_sync_state(SyncState::Idle);
                        }
                    }
                    ChainEvent::BackfillSyncStarted => {
                        network_handle.update_sync_state(SyncState::Syncing);
                    }
                    ChainEvent::FatalError => {
                        error!(target: "reth::cli", "Fatal error in consensus engine");
                        res = Err(eyre::eyre!("Fatal error in consensus engine"));
                        break
                    }
                    ChainEvent::Handler(ev) => {
                        if let Some(head) = ev.canonical_header() {
                            // Once we're progressing via live sync, we can consider the node is not syncing anymore
                            network_handle.update_sync_state(SyncState::Idle);
                            let head_block = Head {
                                number: head.number(),
                                hash: head.hash(),
                                difficulty: head.difficulty(),
                                timestamp: head.timestamp(),
                                total_difficulty: chainspec.final_paris_total_difficulty()
                                    .filter(|_| chainspec.is_paris_active_at_block(head.number()))
                                    .unwrap_or_default(),
                            };
                            network_handle.update_status(head_block);

                            let updated = BlockRangeUpdate {
                                earliest: provider.earliest_block_number().unwrap_or_default(),
                                latest: head.number(),
                                latest_hash: head.hash(),
                            };
                            network_handle.update_block_range(updated);
                        }
                        event_sender.notify(ev);
                    }
                }
            }
            Some(payload) = built_payloads.next(), if !built_payloads.is_terminated() => {
                if let Some(executed_block) = payload.executed_block() {
                    debug!(target: "reth::cli", block=?executed_block.recovered_block.num_hash(),  "inserting built payload");
                    orchestrator.handler_mut().handler_mut().on_event(EngineApiRequest::InsertExecutedBlock(executed_block).into());
                }
            }
            shutdown_req = &mut shutdown_rx => {
                if let Ok(req) = shutdown_req {
                    debug!(target: "reth::cli", "received engine shutdown request");
                    orchestrator.handler_mut().handler_mut().on_event(
                        FromOrchestrator::Terminate { tx: req.done_tx }.into()
                    );
                }
            }
            _guard = &mut on_graceful_shutdown => {
                // Shutdown signal received.
                // Send Terminate so the engine OS thread can exit cleanly before we
                // drop the orchestrator.
                debug!(target: "reth::cli", "shutdown signal received, terminating engine");
                let (done_tx, done_rx) = oneshot::channel();
                orchestrator.handler_mut().handler_mut().on_event(
                    FromOrchestrator::Terminate { tx: done_tx }.into()
                );
                let _ = done_rx.await;
                break;
            }
        }
    }

    let _ = exit.send(res);
};
ctx.task_executor()
    .spawn_critical_with_graceful_shutdown_signal("consensus engine", consensus_engine);

    fn poll_next_event(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<ChainEvent<T::Event>> {
        let this = self.get_mut();

        // This loop polls the components
        //
        // 1. Polls the backfill sync to completion, if active.
        // 2. Advances the chain by polling the handler.
        'outer: loop {
            // try to poll the backfill sync to completion, if active
            match this.backfill_sync.poll(cx) {
                Poll::Ready(backfill_sync_event) => match backfill_sync_event {
                    BackfillEvent::Started(_) => {
                        // notify handler that backfill sync started
                        this.handler.on_event(FromOrchestrator::BackfillSyncStarted);
                        return Poll::Ready(ChainEvent::BackfillSyncStarted);
                    }
                    BackfillEvent::Finished(res) => {
                        return match res {
                            Ok(ctrl) => {
                                tracing::debug!(?ctrl, "backfill sync finished");
                                // notify handler that backfill sync finished
                                this.handler.on_event(FromOrchestrator::BackfillSyncFinished(ctrl));
                                Poll::Ready(ChainEvent::BackfillSyncFinished)
                            }
                            Err(err) => {
                                tracing::error!( %err, "backfill sync failed");
                                Poll::Ready(ChainEvent::FatalError)
                            }
                        }
                    }
                    BackfillEvent::TaskDropped(err) => {
                        tracing::error!( %err, "backfill sync task dropped");
                        return Poll::Ready(ChainEvent::FatalError);
                    }
                },
                Poll::Pending => {}
            }

            // poll the handler for the next event
            match this.handler.poll(cx) {
                Poll::Ready(handler_event) => {
                    match handler_event {
                        HandlerEvent::BackfillAction(action) => {
                            // forward action to backfill_sync
                            this.backfill_sync.on_action(action);
                        }
                        HandlerEvent::Event(ev) => {
                            // bubble up the event
                            return Poll::Ready(ChainEvent::Handler(ev));
                        }
                        HandlerEvent::FatalError => {
                            error!(target: "engine::tree", "Fatal error");
                            return Poll::Ready(ChainEvent::FatalError)
                        }
                    }
                }
                Poll::Pending => {
                    // no more events to process
                    break 'outer
                }
            }
        }

        Poll::Pending
    }
}

impl<T, P> Stream for ChainOrchestrator<T, P>
where
    T: ChainHandler + Unpin,
    P: BackfillSync + Unpin,
{
    type Item = ChainEvent<T::Event>;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        self.as_mut().poll_next_event(cx).map(Some)
    }
}

impl<T, S, D> ChainHandler for EngineHandler<T, S, D>
where
    T: EngineRequestHandler<Block = D::Block>,
    S: Stream + Send + Sync + Unpin + 'static,
    <S as Stream>::Item: Into<T::Request>,
    D: BlockDownloader,
{
    type Event = T::Event;

    fn on_event(&mut self, event: FromOrchestrator) {
        // delegate event to the handler
        self.handler.on_event(event.into());
    }

    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<HandlerEvent<Self::Event>> {
        loop {
            // drain the handler first
            while let Poll::Ready(ev) = self.handler.poll(cx) {
                match ev {
                    RequestHandlerEvent::HandlerEvent(ev) => {
                        return match ev {
                            HandlerEvent::BackfillAction(target) => {
                                // bubble up backfill sync request
                                self.downloader.on_action(DownloadAction::Clear);
                                Poll::Ready(HandlerEvent::BackfillAction(target))
                            }
                            HandlerEvent::Event(ev) => {
                                // bubble up the event
                                Poll::Ready(HandlerEvent::Event(ev))
                            }
                            HandlerEvent::FatalError => Poll::Ready(HandlerEvent::FatalError),
                        }
                    }
                    RequestHandlerEvent::Download(req) => {
                        // delegate download request to the downloader
                        self.downloader.on_action(DownloadAction::Download(req));
                    }
                }
            }

            // pop the next incoming request
            if let Poll::Ready(Some(req)) = self.incoming_requests.poll_next_unpin(cx) {
                // and delegate the request to the handler
                self.handler.on_event(FromEngine::Request(req.into()));
                // skip downloading in this iteration to allow the handler to process the request
                continue
            }

            // advance the downloader
            if let Poll::Ready(outcome) = self.downloader.poll(cx) {
                if let DownloadOutcome::Blocks(blocks) = outcome {
                    // delegate the downloaded blocks to the handler
                    self.handler.on_event(FromEngine::DownloadedBlocks(blocks));
                }
                continue
            }

            return Poll::Pending
        }
    }
}

impl<Request, N: NodePrimitives> EngineRequestHandler for EngineApiRequestHandler<Request, N>
where
    Request: Send,
{
    type Event = ConsensusEngineEvent<N>;
    type Request = Request;
    type Block = N::Block;

    fn on_event(&mut self, event: FromEngine<Self::Request, Self::Block>) {
        // delegate to the tree
        let _ = self.to_tree.send(event);
    }

    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<RequestHandlerEvent<Self::Event>> {
        let Some(ev) = ready!(self.from_tree.poll_recv(cx)) else {
            return Poll::Ready(RequestHandlerEvent::HandlerEvent(HandlerEvent::FatalError))
        };

        let ev = match ev {
            EngineApiEvent::BeaconConsensus(ev) => {
                RequestHandlerEvent::HandlerEvent(HandlerEvent::Event(ev))
            }
            EngineApiEvent::BackfillAction(action) => {
                RequestHandlerEvent::HandlerEvent(HandlerEvent::BackfillAction(action))
            }
            EngineApiEvent::Download(action) => RequestHandlerEvent::Download(action),
        };
        Poll::Ready(ev)
    }
}

    let full_node = FullNode {
        evm_config: ctx.components().evm_config().clone(),
        pool: ctx.components().pool().clone(),
        network: ctx.components().network().clone(),
        provider: ctx.node_adapter().provider.clone(),
        payload_builder_handle: ctx.components().payload_builder_handle().clone(),
        task_executor: ctx.task_executor().clone(),
        config: ctx.node_config().clone(),
        data_dir: ctx.data_dir().clone(),
        add_ons_handle: RpcHandle {
            rpc_server_handles,
            rpc_registry,
            engine_events,
            beacon_engine_handle,
            engine_shutdown,
        },
    };
    // Notify on node started
    on_node_started.on_event(FullNode::clone(&full_node))?;

    ctx.spawn_ethstats(engine_events_for_ethstats).await?;

    let handle = NodeHandle {
        node_exit_future: NodeExitFuture::new(async { rx.await? }),
        node: full_node,
    };

    Ok(handle)
}

/// Run the engine API handler.
///
/// This will block the current thread and process incoming messages.
pub fn run(mut self) {
    loop {
        // Each iteration has three phases:
        //
        // 1. Non-blocking poll for persistence completion. If the background flush already
        //    landed, absorb the result now so the gap calculation below is fresh.
        // 2. Decide how to wait for the next event. When the canonical-to-persisted gap beyond
        //    the in-memory buffer reaches the backpressure threshold we only block on the
        //    persistence receiver, leaving new engine requests sitting in the unbounded
        //    upstream channel.
        // 3. Handle the event (engine message or persistence completion) and kick off a new
        //    persistence cycle if the threshold is met again.
        //
        // The net effect: when the unbuffered persistence gap reaches the threshold, we stop
        // processing incoming messages and let them queue in the channel. This is only a soft
        // form of backpressure: it delays replies and, more importantly, prevents executing
        // further blocks that would pile up in the persistence queue - where each block
        // carries heavier state (eg. trie updates) than the raw payload sitting in the engine
        // channel.
        //
        // Standard Ethereum CLs won't truly back off - the engine API has no
        // backpressure semantics, and CLs typically timeout after ≈8s and resend - so
        // this cannot prevent the incoming channel from growing under sustained load.
        // But it shifts the bottleneck to the lighter-weight incoming queue rather than
        // the costlier persistence pipeline. Other clients that respect reply latency
        // can treat the delayed responses as a signal to chill out.
        match self.try_poll_persistence() {
            Ok(true) => {
                if let Err(err) = self.advance_persistence() {
                    error!(target: "engine::tree", %err, "Advancing persistence failed");
                    return
                }
                continue;
            }
            Ok(false) => {}
            Err(err) => {
                error!(target: "engine::tree", %err, "Polling persistence failed");
                return
            }
        }

        let event = if self.should_backpressure() {
            self.metrics.engine.backpressure_active.set(1.0);
            let stall_start = Instant::now();
            let event = self.wait_for_persistence_event();
            self.metrics.engine.backpressure_stall_duration.record(stall_start.elapsed());
            event
        } else {
            self.metrics.engine.backpressure_active.set(0.0);
            self.wait_for_event()
        };

        match event {
            LoopEvent::EngineMessage(msg) => {
                debug!(target: "engine::tree", %msg, "received new engine message");
                match self.on_engine_message(msg) {
                    Ok(ops::ControlFlow::Break(())) => return,
                    Ok(ops::ControlFlow::Continue(())) => {}
                    Err(fatal) => {
                        error!(target: "engine::tree", %fatal, "insert block fatal error");
                        return
                    }
                }
            }
            LoopEvent::PersistenceComplete { result, start_time } => {
                if let Err(err) = self.on_persistence_complete(result, start_time) {
                    error!(target: "engine::tree", %err, "Persistence complete handling failed");
                    return
                }
            }
            LoopEvent::PayloadBuildFinished => {}
            LoopEvent::Disconnected => {
                error!(target: "engine::tree", "Channel disconnected");
                return
            }
        }

        // Always check if we need to trigger new persistence after any event:
        // - After engine messages: new blocks may have been inserted that exceed the
        //   persistence threshold
        // - After persistence completion: we can now persist more blocks if needed
        if let Err(err) = self.advance_persistence() {
            error!(target: "engine::tree", %err, "Advancing persistence failed");
            return
        }
    }
}

/// How many canonical blocks are retained in memory. A large count means persistence is
/// falling behind execution.
fn persistence_gap(&self) -> u64 {
    self.canonical_in_memory_state.canonical_chain().count() as u64
}

/// How many blocks beyond the configured in-memory buffer are awaiting persistence.
fn persistence_backpressure_gap(&self) -> u64 {
    self.persistence_gap().saturating_sub(self.config.memory_block_buffer_target())
}

/// Returns `true` when the main loop should stop draining the tree input channel.
///
/// This is the case when persistence is already running and the number of blocks beyond the
/// configured in-memory buffer has reached the configured threshold.
fn should_backpressure(&self) -> bool {
    self.persistence_state.in_progress() &&
        self.persistence_backpressure_gap() >=
            self.config.persistence_backpressure_threshold()
}

/// Blocks until the in-flight persistence task completes, used when we are under
/// backpressure.
///
/// Unlike `wait_for_event`, this deliberately does not read from the tree input channel. Any
/// requests sent to the tree remain queued upstream until persistence catches up.
fn wait_for_persistence_event(&mut self) -> LoopEvent<T, N> {
    let maybe_persistence = self.persistence_state.rx.take();

    if let Some((persistence_rx, start_time, _action)) = maybe_persistence {
        match persistence_rx.recv() {
            Ok(result) => LoopEvent::PersistenceComplete { result, start_time },
            Err(_) => LoopEvent::Disconnected,
        }
    } else {
        self.wait_for_event()
    }
}

/// Blocks until the next event is ready.
///
/// Uses biased selection to prioritize persistence completion so in-memory state is updated and
/// further writes are unblocked.
fn wait_for_event(&mut self) -> LoopEvent<T, N> {
    // Take ownership of persistence rx if present
    let maybe_persistence = self.persistence_state.rx.take();

    if let Some((persistence_rx, start_time, action)) = maybe_persistence {
        // Biased select prioritizes persistence completion to update in memory state and
        // unblock further writes
        crossbeam_channel::select_biased! {
            recv(persistence_rx) -> result => {
                // Don't put it back - consumed (oneshot-like behavior)
                match result {
                    Ok(result) => LoopEvent::PersistenceComplete {
                        result,
                        start_time,
                    },
                    Err(_) => LoopEvent::Disconnected,
                }
            },
            recv(self.payload_build_finished) -> result => {
                // Put the persistence rx back - we didn't consume it.
                self.persistence_state.rx = Some((persistence_rx, start_time, action));
                match result {
                    Ok(()) => LoopEvent::PayloadBuildFinished,
                    Err(_) => LoopEvent::Disconnected,
                }
            },
            recv(self.incoming) -> msg => {
                // Put the persistence rx back - we didn't consume it
                self.persistence_state.rx = Some((persistence_rx, start_time, action));
                match msg {
                    Ok(m) => LoopEvent::EngineMessage(m),
                    Err(_) => LoopEvent::Disconnected,
                }
            },
        }
    } else {
        // No persistence in progress - wait on an incoming message or payload job completion.
        crossbeam_channel::select_biased! {
            recv(self.payload_build_finished) -> result => match result {
                Ok(()) => LoopEvent::PayloadBuildFinished,
                Err(_) => LoopEvent::Disconnected,
            },
            recv(self.incoming) -> msg => match msg {
                Ok(m) => LoopEvent::EngineMessage(m),
                Err(_) => LoopEvent::Disconnected,
            },
        }
    }
}

fn persist_blocks(&mut self, input: SaveBlocksInput<N>) {
    let highest_num_hash = input.last_block();
    debug!(target: "engine::tree", count=input.persist_rest_blocks().len(), blocks = ?input.persist_rest_blocks().iter().map(|block| block.recovered_block().num_hash()).collect::<Vec<_>>(), "Persisting blocks");

    let (tx, rx) = crossbeam_channel::bounded(1);
    let _ = self.persistence.save_blocks(input, tx);

    self.persistence_state.start_save(highest_num_hash, rx);
}

/// Triggers new persistence actions if no persistence task is currently in progress.
///
/// This checks if we need to remove blocks (disk reorg) or save new blocks to disk.
/// Persistence completion is handled separately via the `wait_for_event` method.
fn advance_persistence(&mut self) -> Result<(), AdvancePersistenceError> {
    if !self.persistence_state.in_progress() {
        let payload_build_active = self.payload_builds.is_active();
        if let Some(new_tip_num) = self.find_disk_reorg()? {
            self.remove_blocks(new_tip_num)
        } else if self.backfill_sync_state.is_pending_revalidation() &&
            !payload_build_active &&
            self.persistence_state.last_state_trie_persisted_block !=
                self.persistence_state.last_persisted_block
        {
            let Some(input) = self.get_save_blocks_input(PersistTarget::Persisted) else {
                return Err(AdvancePersistenceError::StateTrieCatchupUnavailable)
            };
            self.persist_blocks(input);
        } else if self.backfill_sync_state.is_pending_revalidation() && !payload_build_active {
            self.revalidate_pending_backfill()?;
        } else if let Some(input) = self.get_save_blocks_input(PersistTarget::Threshold) {
            self.persist_blocks(input);
        }
    }

    Ok(())
}

fn on_persistence_complete(
    &mut self,
    result: PersistenceResult,
    start_time: Instant,
) -> Result<(), AdvancePersistenceError> {
    self.metrics.engine.persistence_duration.record(start_time.elapsed());

    let PersistenceResult { last_block, last_state_trie_block, commit_duration } = result;
    debug_assert!(
        last_state_trie_block.number <= last_block.number,
        "state/trie frontier cannot exceed the last persisted block"
    );

    debug!(target: "engine::tree", ?last_block, ?last_state_trie_block, elapsed=?start_time.elapsed(), "Finished persisting, calling finish");
    self.persistence_state.finish(last_block, last_state_trie_block);

    let last_block_number = last_block.number;

    // Evict cached changesets for blocks below the eviction threshold.
    // Keep at least CHANGESET_CACHE_RETENTION_BLOCKS from the persisted tip, and also respect
    // the finalized block if set.
    let min_threshold = last_block_number.saturating_sub(CHANGESET_CACHE_RETENTION_BLOCKS);
    let eviction_threshold =
        if let Some(finalized) = self.canonical_in_memory_state.get_finalized_num_hash() {
            // Use the minimum of finalized block and retention threshold to be conservative
            finalized.number.min(min_threshold)
        } else {
            // When finalized is not set (e.g., on L2s), use the retention threshold
            min_threshold
        };
    debug!(
        target: "engine::tree",
        last_persisted = last_block_number,
        finalized_number = ?self.canonical_in_memory_state.get_finalized_num_hash().map(|f| f.number),
        eviction_threshold,
        "Evicting changesets below threshold"
    );
    self.state.tree_state.overlay_manager.evict_cached_changesets(eviction_threshold);

    self.on_new_persisted_block()?;

    self.purge_timing_stats(last_block_number, commit_duration);

    Ok(())
}

/// Emits an outgoing event to the engine.
fn emit_event(&mut self, event: impl Into<EngineApiEvent<N>>) {
    let event = event.into();

    if let EngineApiEvent::BackfillAction(action) = event {
        debug_assert_eq!(
            self.backfill_sync_state,
            BackfillSyncState::Idle,
            "backfill action should only be emitted when backfill is idle"
        );

        let persistence_in_progress = self.persistence_state.in_progress();
        let state_trie_needs_catchup = self.persistence_state.last_state_trie_persisted_block !=
            self.persistence_state.last_persisted_block;
        if self.payload_builds.is_active() ||
            persistence_in_progress ||
            state_trie_needs_catchup
        {
            // Backfill can remove the same in-memory blocks as an active payload job or a
            // persistence task. Enter pending mode to prevent new payload jobs and
            // re-evaluate the current sync target after all readers and writes drain.
            debug!(
                target: "engine::tree",
                last_persisted_block = self.persistence_state.last_persisted_block.number,
                last_state_trie_persisted_block = self
                    .persistence_state
                    .last_state_trie_persisted_block
                    .number,
                "deferring backfill until persistence and payload jobs drain"
            );
            self.backfill_sync_state = BackfillSyncState::PendingRevalidation;
            return
        }

        self.dispatch_backfill_action(action);
        return
    }

    self.send_event(event);
}

/// Dispatches a validated backfill action to the orchestrator.
fn dispatch_backfill_action(&mut self, action: BackfillAction) {
    debug_assert!(
        self.backfill_sync_state.is_idle() ||
            self.backfill_sync_state.is_pending_revalidation(),
        "backfill action can only be dispatched while idle or pending revalidation"
    );
    self.backfill_sync_state = BackfillSyncState::Pending;
    self.metrics.engine.pipeline_runs.increment(1);
    debug!(target: "engine::tree", "emitting backfill action event");
    self.send_event(EngineApiEvent::BackfillAction(action));
}

/// Sends an event to the orchestrator.
fn send_event(&self, event: EngineApiEvent<N>) {
    let _ = self.outgoing.send(event).inspect_err(
        |err| error!(target: "engine::tree", "Failed to send internal event: {err:?}"),
    );
}

/// Handles a message from the engine.
///
/// Returns `ControlFlow::Break(())` if the engine should terminate.
fn on_engine_message(
    &mut self,
    msg: FromEngine<EngineApiRequest<T, N>, N::Block>,
) -> Result<ops::ControlFlow<()>, InsertBlockFatalError> {
    match msg {
        FromEngine::Event(event) => match event {
            FromOrchestrator::BackfillSyncStarted => {
                debug!(target: "engine::tree", "received backfill sync started event");
                self.backfill_sync_state = BackfillSyncState::Active;
            }
            FromOrchestrator::BackfillSyncFinished(ctrl) => {
                self.on_backfill_sync_finished(ctrl)?;
            }
            FromOrchestrator::Terminate { tx } => {
                debug!(target: "engine::tree", "received terminate request");
                if let Err(err) = self.finish_termination(tx) {
                    error!(target: "engine::tree", %err, "Termination failed");
                }
                return Ok(ops::ControlFlow::Break(()))
            }
        },

fn on_backfill_sync_finished(
    &mut self,
    ctrl: ControlFlow,
) -> Result<(), InsertBlockFatalError> {
    debug!(target: "engine::tree", "received backfill sync finished event");
    self.backfill_sync_state = BackfillSyncState::Idle;

    // Pipeline unwound, memorize the invalid block and wait for CL for next sync target.
    let backfill_height = if let ControlFlow::Unwind { bad_block, target } = &ctrl {
        warn!(target: "engine::tree", invalid_block=?bad_block, "Bad block detected in unwind");
        // update the `invalid_headers` cache with the new invalid header
        self.state.invalid_headers.insert(**bad_block);

        // if this was an unwind then the target is the new height
        Some(*target)
    } else {
        // backfill height is the block number that the backfill finished at
        ctrl.block_number()
    };

    // backfill height is the block number that the backfill finished at
    let Some(backfill_height) = backfill_height else { return Ok(()) };

    // state house keeping after backfill sync
    // remove all executed blocks below the backfill height
    //
    // We set the `finalized_num` to `Some(backfill_height)` to ensure we remove all state
    // before that
    let Some(backfill_num_hash) = self
        .provider
        .block_hash(backfill_height)?
        .map(|hash| BlockNumHash { hash, number: backfill_height })
    else {
        debug!(target: "engine::tree", ?ctrl, "Backfill block not found");
        return Ok(())
    };

    if ctrl.is_unwind() {
        // the node reset so we need to clear everything above that height so that backfill
        // height is the new canonical block.
        self.state.set_pending_sparse_trie_prune(false);
        self.state.tree_state.reset(backfill_num_hash)
    } else {
        self.state.tree_state.remove_until(
            backfill_num_hash,
            self.persistence_state.last_persisted_block.hash,
            Some(backfill_num_hash),
        );
    }

    self.metrics.engine.executed_blocks.set(self.state.tree_state.block_count() as f64);
    self.metrics.tree.canonical_chain_height.set(backfill_height as f64);

    // remove all buffered blocks below the backfill height
    self.state.buffer.remove_old_blocks(backfill_height);
    self.purge_timing_stats(backfill_height, None);
    // we remove all entries because now we're synced to the backfill target and consider this
    // the canonical chain
    self.canonical_in_memory_state.clear_state();

    if let Ok(Some(new_head)) = self.provider.sealed_header(backfill_height) {
        // update the tracked chain height, after backfill sync both the canonical height and
        // persisted height are the same
        self.state.tree_state.set_canonical_head(new_head.num_hash());
        self.persistence_state.finish(new_head.num_hash(), new_head.num_hash());

        // update the tracked canonical head
        self.canonical_in_memory_state.set_canonical_head(new_head);

        // If the pipeline reached the head of the syncing FCU, apply its safe and finalized
        // blocks now that the head is canonical. An unwind must wait for a new FCU because the
        // supplied sync target may have been invalidated.
        if !ctrl.is_unwind() {
            self.on_canonicalized_sync_target(backfill_num_hash.hash);
        }
    }

    // check if we need to run backfill again by comparing the most recent backfill target
    // height to the backfill height
    let Some(sync_target_state) = self.state.forkchoice_state_tracker.sync_target_state()
    else {
        return Ok(())
    };
    if !self.engine_kind.is_opstack() && sync_target_state.finalized_block_hash.is_zero() {
        // no finalized block, can't check distance on non-OP Stack chains
        return Ok(())
    }
    let target_hash = self.backfill_target_hash(sync_target_state);
    if target_hash.is_zero() {
        return Ok(())
    }
    // get the block number of the backfill target block, if we have it buffered
    let newest_target = self.state.buffer.block(&target_hash).map(|block| block.number());

    // The block number that the backfill finished at - if the progress or newest target is
    // None then we can't check the distance anyways.
    //
    // If both are Some, we perform another distance check and return the desired backfill
    // target
    if let Some(backfill_target) =
        ctrl.block_number().zip(newest_target).and_then(|(progress, target_number)| {
            // Determines whether or not we should run backfill again, in case
            // the new gap is still large enough and requires running backfill again
            self.backfill_sync_target(progress, target_number, None)
        })
    {
        // request another backfill run
        self.emit_event(EngineApiEvent::BackfillAction(BackfillAction::Start(
            backfill_target.into(),
        )));
        return Ok(())
    };

    // Check if there are more blocks to sync between current head and FCU target
    if let Some(lowest_buffered) =
        self.state.buffer.lowest_ancestor(&sync_target_state.head_block_hash)
    {
        let current_head_num = self.state.tree_state.current_canonical_head.number;
        let target_head_num = lowest_buffered.number();

        if let Some(distance) = self.distance_from_local_tip(current_head_num, target_head_num)
        {
            // There are blocks between current head and FCU target, download them
            debug!(
                target: "engine::tree",
                %current_head_num,
                %target_head_num,
                %distance,
                "Backfill complete, downloading remaining blocks to reach FCU target"
            );

            self.emit_event(EngineApiEvent::Download(
                DownloadRequest::block_range(lowest_buffered.parent_hash(), distance)
                    .with_access_lists(self.should_download_access_lists()),
            ));
            return Ok(());
        }
    } else {
        // We don't have the head block or any of its ancestors buffered. Request
        // a download for the head block which will then trigger further sync.
        debug!(
            target: "engine::tree",
            head_hash = %sync_target_state.head_block_hash,
            "Backfill complete but head block not buffered, requesting download"
        );
        self.emit_event(EngineApiEvent::Download(
            DownloadRequest::single_block(sync_target_state.head_block_hash)
                .with_access_lists(self.should_download_access_lists()),
        ));
        return Ok(());
    }

    // try to close the gap by executing buffered blocks that are child blocks of the new head
    self.try_connect_buffered_blocks(self.state.tree_state.current_canonical_head)
}

fn on_new_payload(
    &mut self,
    payload: T::ExecutionData,
) -> Result<TreeOutcome<PayloadStatus>, InsertBlockProcessingError> {
    let _thread_resource_usage =
        self.metrics.engine.new_payload.measure_thread_resource_usage();
    trace!(target: "engine::tree", "invoked new payload");

    // start timing for the new payload process
    let start = Instant::now();

    // Ensures that the given payload does not violate any consensus rules that concern the
    // block's layout, like:
    //    - missing or invalid base fee
    //    - invalid extra data
    //    - invalid transactions
    //    - incorrect hash
    //    - the versioned hashes passed with the payload do not exactly match transaction
    //      versioned hashes
    //    - the block does not contain blob transactions if it is pre-cancun
    //
    // This validates the following engine API rule:
    //
    // 3. Given the expected array of blob versioned hashes client software **MUST** run its
    //    validation by taking the following steps:
    //
    //   1. Obtain the actual array by concatenating blob versioned hashes lists
    //      (`tx.blob_versioned_hashes`) of each [blob
    //      transaction](https://eips.ethereum.org/EIPS/eip-4844#new-transaction-type) included
    //      in the payload, respecting the order of inclusion. If the payload has no blob
    //      transactions the expected array **MUST** be `[]`.
    //
    //   2. Return `{status: INVALID, latestValidHash: null, validationError: errorMessage |
    //      null}` if the expected and the actual arrays don't match.
    //
    // This validation **MUST** be instantly run in all cases even during active sync process.

    let num_hash = payload.num_hash();
    let engine_event = ConsensusEngineEvent::BlockReceived(num_hash);
    self.emit_event(EngineApiEvent::BeaconConsensus(engine_event));

    let block_hash = num_hash.hash;

    // Check for invalid ancestors
    if let Some(invalid) = self.find_invalid_ancestor(&payload) {
        let status = self.handle_invalid_ancestor_payload(payload, invalid)?;
        return Ok(TreeOutcome::new(status));
    }

    // record pre-execution phase duration
    self.metrics.block_validation.record_payload_validation(start.elapsed().as_secs_f64());

    let mut outcome = if self.backfill_sync_state.is_idle() {
        self.try_insert_payload(payload)?.into_outcome()
    } else {
        TreeOutcome::new(self.try_buffer_payload(payload)?)
    };

    // if the block is valid and it is the current sync target head, make it canonical
    if outcome.outcome.is_valid() && self.is_sync_target_head(block_hash) {
        // Only create the canonical event if this block isn't already the canonical head
        if self.state.tree_state.canonical_block_hash() != block_hash {
            outcome = outcome.with_event(TreeEvent::TreeAction(TreeAction::MakeCanonical {
                sync_target_head: block_hash,
            }));
        }
    }

    // record total newPayload duration
    self.metrics.block_validation.total_duration.record(start.elapsed().as_secs_f64());

    Ok(outcome)
}

fn validate_forkchoice_state(
    &mut self,
    state: ForkchoiceState,
) -> ProviderResult<Option<OnForkChoiceUpdated>> {
    if state.head_block_hash.is_zero() {
        return Ok(Some(OnForkChoiceUpdated::invalid_state()));
    }

    // Check if the new head hash is connected to any ancestor that we previously marked as
    // invalid
    let lowest_buffered_ancestor_fcu = self.lowest_buffered_ancestor_or(state.head_block_hash);
    if let Some(status) = self.check_invalid_ancestor(lowest_buffered_ancestor_fcu)? {
        return Ok(Some(OnForkChoiceUpdated::with_invalid(status)));
    }

    if !self.backfill_sync_state.is_idle() {
        // We can only process new forkchoice updates if the pipeline is idle, since it requires
        // exclusive access to the database
        trace!(target: "engine::tree", "Pipeline is syncing, skipping forkchoice update");
        return Ok(Some(OnForkChoiceUpdated::syncing()));
    }

    Ok(None)
}

fn get_save_blocks_input(&self, target: PersistTarget) -> Option<SaveBlocksInput<N>> {
    // We will calculate the state root using the database, so we need to be sure there are no
    // changes
    debug_assert!(!self.persistence_state.in_progress());

    let prev_partial_state_trie = self.persistence_state.last_state_trie_persisted_block.number;
    let prev_db_tip = self.persistence_state.last_persisted_block.number;
    let canonical_head_number = self.state.tree_state.canonical_block_number();

    let (new_db_tip, new_partial_state_trie) = match target {
        PersistTarget::Head => (canonical_head_number, canonical_head_number),
        PersistTarget::Persisted => {
            // Catch-up persistence is the transition into pipeline sync, so it deliberately
            // runs while backfill is pending and bypasses the normal threshold gates.
            debug_assert!(self.backfill_sync_state.is_pending_revalidation());
            debug_assert!(!self.payload_builds.is_active());
            (prev_db_tip, prev_db_tip)
        }
        PersistTarget::Threshold => {
            if (self.config.suppress_persistence_during_build() &&
                self.payload_builds.is_active()) ||
                !self.backfill_sync_state.is_idle()
            {
                return None
            }

            let persistence_threshold =
                usize::try_from(self.config.persistence_threshold()).unwrap_or(usize::MAX);
            if self.canonical_in_memory_state.canonical_chain().count() <= persistence_threshold
            {
                return None
            }

            let new_db_tip =
                canonical_head_number.saturating_sub(self.config.memory_block_buffer_target());
            if new_db_tip <= prev_db_tip {
                return None
            }

            let new_partial_state_trie = new_db_tip
                .saturating_sub(self.config.num_state_masking_blocks())
                .max(prev_partial_state_trie);
            (new_db_tip, new_partial_state_trie)
        }
    };

    debug_assert!(
        new_db_tip >= prev_db_tip,
        "disk reorg must be resolved before saving blocks"
    );
    debug_assert!(
        new_partial_state_trie >= prev_partial_state_trie,
        "disk reorg must be resolved before saving state/trie"
    );

    if new_db_tip == prev_db_tip && new_partial_state_trie == prev_partial_state_trie {
        return None
    }

    let mut blocks = Vec::new();
    let mut current_hash = self.state.tree_state.canonical_block_hash();

    debug!(
        target: "engine::tree",
        ?current_hash,
        ?prev_partial_state_trie,
        ?prev_db_tip,
        ?canonical_head_number,
        ?new_partial_state_trie,
        ?new_db_tip,
        target = ?target,
        "Returning save input"
    );
    while let Some(block) = self.state.tree_state.blocks_by_hash.get(&current_hash) {
        if block.recovered_block().number() <= prev_partial_state_trie {
            break;
        }

        if block.recovered_block().number() <= new_db_tip {
            blocks.push(block.clone());
        }

        current_hash = block.recovered_block().parent_hash();
    }

    // Reverse the order so that the oldest block comes first
    blocks.reverse();

    Some(SaveBlocksInput::new(
        blocks,
        prev_db_tip,
        prev_partial_state_trie,
        new_db_tip,
        new_partial_state_trie,
    ))
}

BeaconEngineMessage::NewPayload { payload, tx } => {
    let start = Instant::now();
    let gas_used = payload.gas_used();
    let num_hash = payload.num_hash();
    let mut output = self.on_new_payload(payload);
    self.metrics.engine.new_payload.update_response_metrics(
        start,
        &mut self.metrics.engine.forkchoice_updated.latest_finish_at,
        &output,
        gas_used,
    );

    let maybe_event =
        output.as_mut().ok().and_then(|out| out.event.take());

    // emit response
    if let Err(err) =
        tx.send(output.map(|o| o.outcome).map_err(Into::into))
    {
        warn!(target: "engine::tree", payload=?num_hash, elapsed=?start.elapsed(), "Failed to deliver newPayload response, receiver dropped (request cancelled): {err:?}");
        self.metrics
            .engine
            .failed_new_payload_response_deliveries
            .increment(1);
    }

    // handle the event if any
    self.on_maybe_tree_event(maybe_event)?;
}

fn on_canonical_chain_update(&mut self, chain_update: NewCanonicalChain<N>) {
    trace!(target: "engine::tree", new_blocks = %chain_update.new_block_count(), reorged_blocks =  %chain_update.reorged_block_count(), "applying new chain update");
    let start = Instant::now();

    // update the tracked canonical head
    self.state.tree_state.set_canonical_head(chain_update.tip().num_hash());

    let tip = chain_update.tip().clone_sealed_header();
    let notification = chain_update.to_chain_notification();

    // reinsert any missing reorged blocks
    if let NewCanonicalChain::Reorg { new, old } = &chain_update {
        let new_first = new.first().map(|first| first.recovered_block().num_hash());
        let old_first = old.first().map(|first| first.recovered_block().num_hash());
        trace!(target: "engine::tree", ?new_first, ?old_first, "Reorg detected, new and old first blocks");

        self.state.set_pending_sparse_trie_prune(false);
        self.update_reorg_metrics(old.len(), old_first);
        self.reinsert_reorged_blocks(new.clone());
        self.reinsert_reorged_blocks(old.clone());
    }

    // update the tracked in-memory state with the new chain
    self.canonical_in_memory_state.update_chain(chain_update);
    self.canonical_in_memory_state.set_canonical_head(tip.clone());
    self.payload_validator.on_canonical_head_changed(tip.hash(), &self.state);

    // Update metrics based on new tip
    self.metrics.tree.canonical_chain_height.set(tip.number() as f64);

    // sends an event to all active listeners about the new canonical chain
    self.canonical_in_memory_state.notify_canon_state(notification);

    // emit event
    self.emit_event(ConsensusEngineEvent::CanonicalChainCommitted(
        Box::new(tip),
        start.elapsed(),
    ));
}

impl<N: NetworkPrimitives> Future for NetworkManager<N> {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let start = Instant::now();
        let mut poll_durations = NetworkManagerPollDurations::default();

        let this = self.get_mut();

        // poll new block imports (expected to be a noop for POS)
        while let Poll::Ready(outcome) = this.block_import.poll(cx) {
            this.on_block_import_result(outcome);
        }

        // These loops drive the entire state of network and does a lot of work. Under heavy load
        // (many messages/events), data may arrive faster than it can be processed (incoming
        // messages/requests -> events), and it is possible that more data has already arrived by
        // the time an internal event is processed. Which could turn this loop into a busy loop.
        // Without yielding back to the executor, it can starve other tasks waiting on that
        // executor to execute them, or drive underlying resources To prevent this, we
        // preemptively return control when the `budget` is exhausted. The value itself is chosen
        // somewhat arbitrarily, it is high enough so the swarm can make meaningful progress but
        // low enough that this loop does not starve other tasks for too long. If the budget is
        // exhausted we manually yield back control to the (coop) scheduler. This manual yield
        // point should prevent situations where polling appears to be frozen. See also
        // <https://tokio.rs/blog/2020-04-preemption> And tokio's docs on cooperative scheduling
        // <https://docs.rs/tokio/latest/tokio/task/#cooperative-scheduling>
        //
        // Testing has shown that this loop naturally reaches the pending state within 1-5
        // iterations in << 100µs in most cases. On average it requires ~50µs, which is inside the
        // range of what's recommended as rule of thumb.
        // <https://ryhl.io/blog/async-what-is-blocking/>

        // process incoming messages from a handle (`TransactionsManager` has one)
        //
        // will only be closed if the channel was deliberately closed since we always have an
        // instance of `NetworkHandle`
        let start_network_handle = Instant::now();
        let maybe_more_handle_messages = poll_nested_stream_with_budget!(
            "net",
            "Network message channel",
            DEFAULT_BUDGET_TRY_DRAIN_NETWORK_HANDLE_CHANNEL,
            this.from_handle_rx.poll_next_unpin(cx),
            |msg| this.on_handle_message(msg),
            error!("Network channel closed");
        );
        poll_durations.acc_network_handle = start_network_handle.elapsed();

        // process incoming messages from the network
        let maybe_more_swarm_events = poll_nested_stream_with_budget!(
            "net",
            "Swarm events stream",
            DEFAULT_BUDGET_TRY_DRAIN_SWARM,
            this.swarm.poll_next_unpin(cx),
            |event| this.on_swarm_event(event),
        );
        poll_durations.acc_swarm =
            start_network_handle.elapsed() - poll_durations.acc_network_handle;

        // all streams are fully drained and import futures pending
        if maybe_more_handle_messages || maybe_more_swarm_events {
            // make sure we're woken up again
            cx.waker().wake_by_ref();
            return Poll::Pending
        }

        this.update_poll_metrics(start, poll_durations);

        Poll::Pending
    }

/// pipeline and its result as a future.
#[track_caller]
pub fn run_as_fut(mut self, target: Option<PipelineTarget>) -> PipelineFut<N> {
    let _ = self.register_metrics();
    Box::pin(async move {
        // NOTE: the tip should only be None if we are in continuous sync mode.
        if let Some(target) = target {
            match target {
                PipelineTarget::Sync(tip) => self.set_tip(tip),
                PipelineTarget::Unwind(target) => {
                    if let Err(err) = self.move_to_static_files() {
                        return (self, Err(err.into()))
                    }
                    if let Err(err) = self.unwind(target, None) {
                        return (self, Err(err))
                    }
                    self.progress.update(target);

                    return (self, Ok(ControlFlow::Continue { block_number: target }))
                }
            }
        }

        let result = self.run_loop().await;
        trace!(target: "sync::pipeline", ?target, ?result, "Pipeline finished");
        (self, result)
    })
}

    fn builder(self) -> StageSetBuilder<Provider> {
        let mut builder = StageSetBuilder::default();

        if self.era_import_source.is_some() {
            builder = builder
                .add_stage(EraStage::new(self.era_import_source, self.stages_config.etl.clone()));
        }

        builder
            .add_stage(HeaderStage::new(
                self.provider,
                self.header_downloader,
                self.tip,
                self.stages_config.etl.clone(),
            ))
            .add_stage(BodyStage::new(self.body_downloader))
    }
}

    fn builder(self) -> StageSetBuilder<Provider> {
        StageSetBuilder::default()
            .add_stage(SenderRecoveryStage::new(
                self.stages_config.sender_recovery,
                self.sender_recovery_prune_mode,
            ))
            .add_stage(ExecutionStage::from_config(
                self.evm_config,
                self.consensus,
                self.stages_config.execution,
                self.stages_config.execution_external_clean_threshold(),
            ))
    }
}

impl<E, Provider> StageSet<Provider> for OfflineStages<E>
where
    E: ConfigureEvm,
    ExecutionStages<E>: StageSet<Provider>,
    PruneSenderRecoveryStage: Stage<Provider>,
    HashingStages: StageSet<Provider>,
    HistoryIndexingStages: StageSet<Provider>,
    PruneStage: Stage<Provider>,
{
    fn builder(self) -> StageSetBuilder<Provider> {
        ExecutionStages::new(
            self.evm_config,
            self.consensus,
            self.stages_config.clone(),
            self.prune_modes.sender_recovery,
        )
        .builder()
        // If sender recovery prune mode is set, add the prune sender recovery stage.
        .add_stage_opt(self.prune_modes.sender_recovery.map(|prune_mode| {
            PruneSenderRecoveryStage::new(prune_mode, self.stages_config.prune.commit_threshold)
        }))
        .add_set(HashingStages { stages_config: self.stages_config.clone() })
        .add_set(HistoryIndexingStages {
            stages_config: self.stages_config.clone(),
            prune_modes: self.prune_modes.clone(),
        })
        // Prune stage should be added after all hashing stages, because otherwise it will
        // delete
        .add_stage(PruneStage::new(
            self.prune_modes.clone(),
            self.stages_config.prune.commit_threshold,
        ))
    }
}

/// execution of each stage, it proceeds to commit it to the database.
///
/// If any stage is unsuccessful at execution, we proceed to
/// unwind. This will undo the progress across the entire pipeline
/// up to the block that caused the error.
///
/// Returns the control flow after it ran the pipeline.
/// This will be [`ControlFlow::Continue`] or [`ControlFlow::NoProgress`] of the _last_ stage in
/// the pipeline (for example the `Finish` stage). Or [`ControlFlow::Unwind`] of the stage
/// that caused the unwind.
pub async fn run_loop(&mut self) -> Result<ControlFlow, PipelineError> {
    self.move_to_static_files()?;

    let mut previous_stage = None;
    for stage_index in 0..self.stages.len() {
        let stage = &self.stages[stage_index];
        let stage_id = stage.id();

        trace!(target: "sync::pipeline", stage = %stage_id, "Executing stage");
        let next = self.execute_stage_to_completion(previous_stage, stage_index).await?;

        trace!(target: "sync::pipeline", stage = %stage_id, ?next, "Completed stage");

        match next {
            ControlFlow::NoProgress { block_number } => {
                if let Some(block_number) = block_number {
                    self.progress.update(block_number);
                }
            }
            ControlFlow::Continue { block_number } => self.progress.update(block_number),
            ControlFlow::Unwind { target, bad_block } => {
                self.unwind(target, Some(bad_block.block.number))?;
                return Ok(ControlFlow::Unwind { target, bad_block })
            }
        }

        previous_stage = Some(
            self.provider_factory
                .provider()?
                .get_stage_checkpoint(stage_id)?
                .unwrap_or_default()
                .block_number,
        );
    }

    Ok(self.progress.next_ctrl())
}

/// Unwind the stages to the target block (exclusive).
///
/// If the unwind is due to a bad block the number of that block should be specified.
pub fn unwind(
    &mut self,
    to: BlockNumber,
    bad_block: Option<BlockNumber>,
) -> Result<(), PipelineError> {
    // Add validation before starting unwind
    let (latest_block, prune_modes, checkpoints) = {
        let provider = self.provider_factory.provider()?;
        (
            provider.last_block_number()?,
            provider.prune_modes_ref().clone(),
            provider.get_prune_checkpoints()?,
        )
    };
    prune_modes.ensure_unwind_target_unpruned(latest_block, to, &checkpoints)?;

    // Unwind stages in reverse order of execution
    let unwind_pipeline = self.stages.iter_mut().rev();

    // Legacy Engine: This prevents a race condition in which the `StaticFileProducer` could
    // attempt to proceed with a finalized block which has been unwinded
    let _locked_sf_producer = self.static_file_producer.lock();

    let mut provider_rw =
        self.provider_factory.unwind_provider_rw()?.disable_long_read_transaction_safety();

    for stage in unwind_pipeline {
        let stage_id = stage.id();
        let span = info_span!("Unwinding", stage = %stage_id);
        let _enter = span.enter();

        let mut checkpoint = provider_rw.get_stage_checkpoint(stage_id)?.unwrap_or_default();
        if checkpoint.block_number < to {
            debug!(
                target: "sync::pipeline",
                from = %checkpoint.block_number,
                %to,
                "Unwind point too far for stage"
            );
            self.event_sender.notify(PipelineEvent::Skipped { stage_id });

            continue
        }

        info!(
            target: "sync::pipeline",
            from = %checkpoint.block_number,
            %to,
            ?bad_block,
            "Starting unwind"
        );
        while checkpoint.block_number > to {
            let unwind_started_at = Instant::now();
            let input = UnwindInput { checkpoint, unwind_to: to, bad_block };
            self.event_sender.notify(PipelineEvent::Unwind { stage_id, input });

            let output = stage.unwind(&provider_rw, input);
            match output {
                Ok(unwind_output) => {
                    checkpoint = unwind_output.checkpoint;
                    info!(
                        target: "sync::pipeline",
                        stage = %stage_id,
                        unwind_to = to,
                        progress = checkpoint.block_number,
                        done = checkpoint.block_number == to,
                        "Stage unwound"
                    );

                    provider_rw.save_stage_checkpoint(stage_id, checkpoint)?;

                    // Notify event listeners and update metrics.
                    self.event_sender
                        .notify(PipelineEvent::Unwound { stage_id, result: unwind_output });

                    if let Some(metrics_tx) = &mut self.metrics_tx {
                        let _ = metrics_tx.send(MetricEvent::StageCheckpoint {
                            stage_id,
                            checkpoint,
                            // We assume it was set in the previous execute iteration, so it
                            // doesn't change when we unwind.
                            max_block_number: None,
                            elapsed: unwind_started_at.elapsed(),
                        });
                    }

                    // update finalized and safe block if needed
                    let last_saved_finalized_block_number =
                        provider_rw.last_finalized_block_number()?;

                    // If None, that means the finalized block is not written so we should
                    // always save in that case
                    if last_saved_finalized_block_number.is_none() ||
                        Some(checkpoint.block_number) < last_saved_finalized_block_number
                    {
                        provider_rw.save_finalized_block_number(BlockNumber::from(
                            checkpoint.block_number,
                        ))?;
                    }

                    let last_saved_safe_block_number = provider_rw.last_safe_block_number()?;

                    if last_saved_safe_block_number.is_none() ||
                        Some(checkpoint.block_number) < last_saved_safe_block_number
                    {
                        provider_rw.save_safe_block_number(BlockNumber::from(
                            checkpoint.block_number,
                        ))?;
                    }

                    provider_rw.commit()?;

                    stage.post_unwind_commit()?;

                    provider_rw = self.provider_factory.unwind_provider_rw()?;
                }
                Err(err) => {
                    self.event_sender.notify(PipelineEvent::Error { stage_id });

                    return Err(PipelineError::Stage(StageError::Fatal(Box::new(err))))
                }
            }
        }
    }

    Ok(())
}

    // advance the chain and await payloads built locally to add into the engine api
    // tree handler to prevent re-execution if that block is received as payload from
    // the CL
    loop {
        tokio::select! {
            event = orchestrator.next() => {
                let Some(event) = event else { break };
                debug!(target: "reth::cli", "Event: {event}");
                match event {
                    ChainEvent::BackfillSyncFinished => {
                        if terminate_after_backfill {
                            debug!(target: "reth::cli", "Terminating after initial backfill");
                            break
                        }
                        if startup_sync_state_idle {
                            network_handle.update_sync_state(SyncState::Idle);
                        }
                    }
                    ChainEvent::BackfillSyncStarted => {
                        network_handle.update_sync_state(SyncState::Syncing);
                    }
                    ChainEvent::FatalError => {
                        error!(target: "reth::cli", "Fatal error in consensus engine");
                        res = Err(eyre::eyre!("Fatal error in consensus engine"));
                        break
                    }
                    ChainEvent::Handler(ev) => {
                        if let Some(head) = ev.canonical_header() {
                            // Once we're progressing via live sync, we can consider the node is not syncing anymore
                            network_handle.update_sync_state(SyncState::Idle);
                            let head_block = Head {
                                number: head.number(),
                                hash: head.hash(),
                                difficulty: head.difficulty(),
                                timestamp: head.timestamp(),
                                total_difficulty: chainspec.final_paris_total_difficulty()
                                    .filter(|_| chainspec.is_paris_active_at_block(head.number()))
                                    .unwrap_or_default(),
                            };
                            network_handle.update_status(head_block);

                            let updated = BlockRangeUpdate {
                                earliest: provider.earliest_block_number().unwrap_or_default(),
                                latest: head.number(),
                                latest_hash: head.hash(),
                            };
                            network_handle.update_block_range(updated);
                        }
                        event_sender.notify(ev);
                    }
                }
            }
            Some(payload) = built_payloads.next(), if !built_payloads.is_terminated() => {
                if let Some(executed_block) = payload.executed_block() {
                    debug!(target: "reth::cli", block=?executed_block.recovered_block.num_hash(),  "inserting built payload");
                    orchestrator.handler_mut().handler_mut().on_event(EngineApiRequest::InsertExecutedBlock(executed_block).into());
                }
            }
            shutdown_req = &mut shutdown_rx => {
                if let Ok(req) = shutdown_req {
                    debug!(target: "reth::cli", "received engine shutdown request");
                    orchestrator.handler_mut().handler_mut().on_event(
                        FromOrchestrator::Terminate { tx: req.done_tx }.into()
                    );
                }
            }
            _guard = &mut on_graceful_shutdown => {
                // Shutdown signal received.
                // Send Terminate so the engine OS thread can exit cleanly before we
                // drop the orchestrator.
                debug!(target: "reth::cli", "shutdown signal received, terminating engine");
                let (done_tx, done_rx) = oneshot::channel();
                orchestrator.handler_mut().handler_mut().on_event(
                    FromOrchestrator::Terminate { tx: done_tx }.into()
                );
                let _ = done_rx.await;
                break;
            }
        }
    }

    let _ = exit.send(res);
};
ctx.task_executor()
    .spawn_critical_with_graceful_shutdown_signal("consensus engine", consensus_engine);

/// Launches the node with the [`DebugNodeLauncher`].
///
/// This is equivalent to [`WithLaunchContext::launch`], but will enable the debugging features,
/// if they are configured.
pub fn launch_with_debug_capabilities(
    self,
) -> <DebugNodeLauncher as LaunchNode<NodeBuilderWithComponents<T, CB, AO>>>::Future
where
    T::Types: DebugNode<NodeAdapter<T, CB::Components>>,
    DebugNodeLauncher: LaunchNode<NodeBuilderWithComponents<T, CB, AO>>,
{
    let Self { builder, task_executor } = self;

    let engine_tree_config = builder.config.tree_config();

    let launcher = DebugNodeLauncher::new(EngineNodeLauncher::new(
        task_executor,
        builder.config.datadir(),
        engine_tree_config,
    ));
    builder.launch_with(launcher)
}

impl<T, CB, AO> NodeBuilderWithComponents<T, CB, AO>
where
    T: FullNodeTypes,
    CB: NodeComponentsBuilder<T>,
    AO: RethRpcAddOns<NodeAdapter<T, CB::Components>>,
{
    /// Launches the node with the given launcher.
    pub fn launch_with<L>(self, launcher: L) -> L::Future
    where
        L: LaunchNode<Self>,
    {
        launcher.launch_node(self)
    }

impl<L, Target, N, AddOns, B> IntoFuture for DebugNodeLauncherFuture<L, Target, N, B>
where
    Target: Send + 'static,
    N: FullNodeComponents<Types: DebugNode<N>>,
    AddOns: RethRpcAddOns<N> + 'static,
    L: LaunchNode<Target, Node = NodeHandle<N, AddOns>> + 'static,
    B: PayloadProvider<ExecutionData = PayloadDataTy<N::Types>> + Clone + 'static,
{
    type Output = eyre::Result<NodeHandle<N, AddOns>>;
    type IntoFuture = Pin<Box<dyn Future<Output = eyre::Result<NodeHandle<N, AddOns>>> + Send>>;

    fn into_future(self) -> Self::IntoFuture {
        Box::pin(self.launch_node())
    }
}

impl<L, Target, N, AddOns> LaunchNode<Target> for DebugNodeLauncher<L>
where
    Target: Send + 'static,
    N: FullNodeComponents<Types: DebugNode<N>>,
    AddOns: RethRpcAddOns<N> + 'static,
    L: LaunchNode<Target, Node = NodeHandle<N, AddOns>> + 'static,
    DefaultDebugBlockProvider<N>: PayloadProvider<ExecutionData = PayloadDataTy<N::Types>> + Clone,
{
    type Node = NodeHandle<N, AddOns>;
    type Future = DebugNodeLauncherFuture<L, Target, N>;

    fn launch_node(self, target: Target) -> Self::Future {
        DebugNodeLauncherFuture {
            inner: self.inner,
            target,
            local_payload_attributes_builder: None,
            map_attributes: None,
            debug_block_provider: None,
            mining_mode: None,
        }
    }
}

async fn launch_node(self) -> eyre::Result<NodeHandle<N, AddOns>> {
    let Self {
        inner,
        target,
        local_payload_attributes_builder,
        map_attributes,
        debug_block_provider,
        mining_mode,
    } = self;

    let handle = inner.launch_node(target).await?;

